def transform(grid):
    """Fill short gaps between successive same-color markers in rows and columns."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for color in {v for row in grid for v in row if v != background}:
        for r in range(h):
            positions = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(positions, positions[1:]):
                if b - a <= 7:
                    for c in range(a + 1, b):
                        if grid[r][c] == background:
                            out[r][c] = 2
        for c in range(w):
            positions = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(positions, positions[1:]):
                if b - a <= 7:
                    for r in range(a + 1, b):
                        if grid[r][c] == background:
                            out[r][c] = 2
    return out

